values ('33deab4c-1189-55d5-a91d-8726ee32c15c', 'free-exercise-db (yuhonas)', 'https://github.com/yuhonas/free-exercise-db', 'Unlicense', 'https://unlicense.org/', 'Seleção e classificação a partir do free-exercise-db (domínio público, Unlicense); textos reescritos em pt-BR.', '2026-10-26', 'Commit f00c92c7dcf1216a928a52c3706c7ce8e2f71ed5. Imagens não usadas (ADR-052).');

   measure_type, is_bodyweight, movement_pattern, load_markers, text_reviewed_at)
values
  ('f609e8e1-b93b-54c0-9745-49195507fa13', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Bench_Press_-_Medium_Grip', 'Supino reto com barra', '["Deite no banco com os olhos sob a barra e os pés firmes no chão.","Segure a barra um pouco mais aberta que a largura dos ombros e retire-a do suporte com os braços estendidos.","Desça a barra de forma controlada até tocar levemente o meio do peito.","Empurre a barra de volta até estender os braços, sem tirar o quadril do banco."]'::jsonb, '["Com cargas altas, treine com alguém para ajudar a devolver a barra ao suporte."]'::jsonb, 'beginner', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('ba3ad075-6f7f-58cf-8da8-efdbea336a49', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Incline_Bench_Press_-_Medium_Grip', 'Supino inclinado com barra', '["Ajuste o banco entre 30° e 45° e deite com os pés firmes no chão.","Retire a barra do suporte com pegada um pouco mais aberta que os ombros.","Desça a barra até a parte alta do peito, com os cotovelos levemente abaixo da linha dos ombros.","Empurre a barra para cima até estender os braços."]'::jsonb, '["Mantenha as escápulas apoiadas no banco durante todo o movimento."]'::jsonb, 'beginner', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('925345ab-a84f-5985-8696-5d8e78ea8404', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Decline_Barbell_Bench_Press', 'Supino declinado com barra', '["Prenda as pernas no apoio do banco declinado e deite com a cabeça na parte mais baixa.","Retire a barra do suporte com pegada um pouco mais aberta que os ombros.","Desça a barra até a parte baixa do peito de forma controlada.","Empurre a barra de volta até estender os braços."]'::jsonb, '["Peça ajuda para retirar e devolver a barra; a posição dificulta alcançar o suporte."]'::jsonb, 'intermediate', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('89aa2c0d-84c6-5556-802a-ca1f50816606', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Bench_Press', 'Supino reto com halteres', '["Sente no banco com um halter sobre cada coxa e deite levando os halteres à altura do peito.","Empurre os halteres para cima até estender os braços, com as palmas voltadas para os pés.","Desça os halteres de forma controlada até a lateral do peito.","Repita, mantendo os pés firmes no chão."]'::jsonb, '["Ao terminar, traga os halteres ao peito e sente-se antes de soltá-los."]'::jsonb, 'beginner', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('c9ffec28-09ed-5912-96e7-a60f7272a292', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Incline_Dumbbell_Press', 'Supino inclinado com halteres', '["Ajuste o banco entre 30° e 45° e deite com um halter em cada mão, na altura dos ombros.","Empurre os halteres para cima até estender os braços.","Desça de forma controlada até os halteres ficarem ao lado da parte alta do peito."]'::jsonb, '["Evite bater os halteres no alto; mantenha o controle do movimento."]'::jsonb, 'beginner', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('b6f24ccb-3e03-581d-9171-588bcb6ba852', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Machine_Bench_Press', 'Supino na máquina', '["Ajuste o assento para que as manoplas fiquem na altura do meio do peito.","Empurre as manoplas para a frente até estender os braços, sem travar os cotovelos.","Volte de forma controlada até sentir o alongamento do peito."]'::jsonb, '["Mantenha as costas apoiadas no encosto."]'::jsonb, 'beginner', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('2bcb89ef-fa8d-5c66-bc2e-5f38a195bdaa', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Smith_Machine_Bench_Press', 'Supino reto no Smith', '["Posicione o banco sob a barra do Smith, alinhada ao meio do peito.","Destrave a barra e desça de forma controlada até tocar levemente o peito.","Empurre até estender os braços e trave a barra ao terminar."]'::jsonb, '["Ajuste as travas de segurança do Smith logo acima do peito."]'::jsonb, 'beginner', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('100dc3eb-01c6-5e7c-96ed-1cb00fc4cda8', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Pushups', 'Flexão de braços', '["Apoie as mãos no chão um pouco mais abertas que os ombros e estenda as pernas.","Mantenha o corpo alinhado da cabeça aos calcanhares.","Desça o peito em direção ao chão dobrando os cotovelos.","Empurre o chão até estender os braços."]'::jsonb, '["Se ficar difícil manter o corpo alinhado, apoie os joelhos ou as mãos num banco."]'::jsonb, 'beginner', 'reps', true, 'h_push', array['wrist_loaded_extension']::text[], '2026-10-27T00:00:00Z'),
  ('e67daba7-c0f9-5abf-8da7-88a8a12034d6', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Incline_Push-Up', 'Flexão inclinada (mãos no banco)', '["Apoie as mãos na borda de um banco firme, um pouco mais abertas que os ombros.","Afaste os pés até o corpo ficar alinhado e inclinado.","Desça o peito até perto do banco e empurre de volta."]'::jsonb, '["Use um banco que não deslize."]'::jsonb, 'beginner', 'reps', true, 'h_push', array['wrist_loaded_extension']::text[], '2026-10-27T00:00:00Z'),
  ('73a5d562-b180-503d-9ad5-e646bbbea4ab', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Push-Ups_With_Feet_Elevated', 'Flexão com pés elevados', '["Apoie os pés num banco e as mãos no chão, um pouco mais abertas que os ombros.","Mantenha o corpo alinhado e desça o peito em direção ao chão.","Empurre até estender os braços."]'::jsonb, '["Não deixe o quadril cair durante a descida."]'::jsonb, 'intermediate', 'reps', true, 'h_push', array['wrist_loaded_extension']::text[], '2026-10-27T00:00:00Z'),
  ('3567e9e4-f577-5e04-9b0a-f8ee03c914f6', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Flyes', 'Crucifixo reto com halteres', '["Deite no banco com os halteres acima do peito e os cotovelos levemente flexionados.","Abra os braços em arco até sentir o alongamento do peito, mantendo a flexão dos cotovelos.","Feche os braços pelo mesmo arco até os halteres se aproximarem."]'::jsonb, '["Não desça além do alongamento confortável dos ombros."]'::jsonb, 'beginner', 'reps', false, 'chest_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('96442052-1130-5eb5-ac2a-525e01a35261', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Incline_Dumbbell_Flyes', 'Crucifixo inclinado com halteres', '["Ajuste o banco entre 30° e 45° e deite com os halteres acima do peito.","Abra os braços em arco com os cotovelos levemente flexionados.","Volte pelo mesmo arco até os halteres se aproximarem."]'::jsonb, '["Use cargas que permitam controlar o arco do início ao fim."]'::jsonb, 'beginner', 'reps', false, 'chest_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('c6e691ab-00b2-55d0-b904-462c1005bfaa', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Butterfly', 'Voador (peck deck)', '["Ajuste o assento para que as manoplas fiquem na altura do peito.","Junte as manoplas à frente do corpo contraindo o peito.","Volte de forma controlada até sentir o alongamento."]'::jsonb, '["Mantenha as costas apoiadas e os ombros afastados das orelhas."]'::jsonb, 'beginner', 'reps', false, 'chest_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('951633d1-d6d5-5888-ba14-0c88ae791ab5', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Cable_Crossover', 'Crossover na polia alta', '["Segure as alças das polias altas e dê um passo à frente, com o tronco levemente inclinado.","Com os cotovelos levemente flexionados, traga as mãos para a frente e para baixo até se encontrarem.","Volte de forma controlada até os braços ficarem abertos."]'::jsonb, '["Mantenha um pé à frente do outro para ter equilíbrio."]'::jsonb, 'beginner', 'reps', false, 'chest_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('e5ca4060-36b8-51f2-8fd7-7d768cf1c373', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Low_Cable_Crossover', 'Crossover na polia baixa', '["Segure as alças das polias baixas e fique de pé entre elas.","Com os cotovelos levemente flexionados, traga as mãos para cima e para a frente até a altura do peito.","Volte de forma controlada."]'::jsonb, '["Evite usar o impulso do tronco."]'::jsonb, 'beginner', 'reps', false, 'chest_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('b436606c-9e32-546e-8fe7-179b742291a4', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dips_-_Chest_Version', 'Paralelas com ênfase no peitoral', '["Apoie-se nas barras paralelas com os braços estendidos.","Incline o tronco à frente e desça dobrando os cotovelos até sentir o alongamento do peito.","Empurre de volta até estender os braços."]'::jsonb, '["Desça só até onde o ombro fica confortável."]'::jsonb, 'intermediate', 'reps', true, 'h_push', array['shoulder_end_range']::text[], '2026-10-27T00:00:00Z'),
  ('05e47a08-dc06-5d29-8bd9-6ebcb1d4dcd2', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Close-Grip_Barbell_Bench_Press', 'Supino fechado com barra', '["Deite no banco e segure a barra com as mãos na largura dos ombros.","Desça a barra até a parte baixa do peito, mantendo os cotovelos próximos ao corpo.","Empurre até estender os braços."]'::jsonb, '["Pegada muito fechada sobrecarrega os punhos; mantenha a largura dos ombros."]'::jsonb, 'intermediate', 'reps', false, 'h_push', array[]::text[], '2026-10-27T00:00:00Z'),
  ('36005811-fef4-562a-a4cb-0b07563f5e8e', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Shoulder_Press', 'Desenvolvimento com halteres', '["Sente no banco com encosto vertical e segure os halteres na altura dos ombros.","Empurre os halteres para cima até estender os braços.","Desça de forma controlada até a altura das orelhas."]'::jsonb, '["Não arqueie a lombar; mantenha as costas apoiadas."]'::jsonb, 'intermediate', 'reps', false, 'v_push', array['overhead']::text[], '2026-10-27T00:00:00Z'),
  ('ff2ee1b1-6c72-588a-a6f6-395543bf699f', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Standing_Military_Press', 'Desenvolvimento militar em pé com barra', '["Segure a barra na altura do peito alto, com pegada um pouco mais aberta que os ombros.","Contraia abdômen e glúteos e empurre a barra para cima até estender os braços.","Desça de forma controlada até o peito alto."]'::jsonb, '["Afaste levemente a cabeça para trás na passagem da barra; não incline o tronco."]'::jsonb, 'intermediate', 'reps', false, 'v_push', array['overhead', 'axial_spine_load']::text[], '2026-10-27T00:00:00Z'),
  ('a6a2afb9-0835-5e1f-97a9-8301884f764a', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Machine_Shoulder_Military_Press', 'Desenvolvimento na máquina', '["Ajuste o assento para que as manoplas fiquem na altura dos ombros.","Empurre as manoplas para cima até estender os braços.","Volte de forma controlada."]'::jsonb, '["Mantenha as costas apoiadas no encosto."]'::jsonb, 'beginner', 'reps', false, 'v_push', array['overhead']::text[], '2026-10-27T00:00:00Z'),
  ('a48f335f-61e0-5e98-b600-914768bb6295', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Arnold_Dumbbell_Press', 'Desenvolvimento Arnold', '["Sente com os halteres à frente dos ombros e as palmas voltadas para você.","Empurre para cima girando os punhos até as palmas ficarem para a frente no alto.","Desça invertendo a rotação até a posição inicial."]'::jsonb, '["Use cargas menores que no desenvolvimento comum."]'::jsonb, 'intermediate', 'reps', false, 'v_push', array['overhead', 'shoulder_end_range']::text[], '2026-10-27T00:00:00Z'),
  ('2a602335-770c-506b-8f69-f13a9cbb9523', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Side_Lateral_Raise', 'Elevação lateral com halteres', '["Em pé, segure os halteres ao lado do corpo com os cotovelos levemente flexionados.","Eleve os braços para os lados até a altura dos ombros.","Desça de forma controlada."]'::jsonb, '["Não use impulso do tronco; prefira cargas leves e controle."]'::jsonb, 'beginner', 'reps', false, 'shoulder_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('b6b4bbd0-49cc-51ea-8bf5-ba01e08920cb', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Cable_Seated_Lateral_Raise', 'Elevação lateral na polia', '["Fique de lado para a polia baixa e segure a alça com a mão mais distante.","Eleve o braço para o lado até a altura do ombro.","Desça de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Mantenha o tronco imóvel."]'::jsonb, 'beginner', 'reps', false, 'shoulder_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('25e3f466-75cd-5fee-9d8a-4718639e0934', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Front_Dumbbell_Raise', 'Elevação frontal com halteres', '["Em pé, segure os halteres à frente das coxas.","Eleve um ou os dois braços à frente até a altura dos ombros.","Desça de forma controlada."]'::jsonb, '["Não balance o tronco para subir a carga."]'::jsonb, 'beginner', 'reps', false, 'shoulder_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('91074a74-50cf-52da-9285-53a2bb976525', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Reverse_Machine_Flyes', 'Crucifixo inverso na máquina', '["Sente de frente para o encosto do voador e segure as manoplas com os braços à frente.","Abra os braços para trás até alinhá-los ao corpo.","Volte de forma controlada."]'::jsonb, '["Mantenha o peito apoiado no encosto."]'::jsonb, 'beginner', 'reps', false, 'shoulder_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('48e7c7d3-4860-56bd-9960-20707015a831', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Reverse_Flyes', 'Crucifixo inverso com halteres', '["Incline o tronco à frente com as costas retas e os halteres pendendo sob o peito.","Abra os braços para os lados até a altura dos ombros.","Desça de forma controlada."]'::jsonb, '["Se sentir a lombar, faça sentado com o peito apoiado num banco inclinado."]'::jsonb, 'beginner', 'reps', false, 'shoulder_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('9d0fca32-b858-556c-9dae-fc3b4428e871', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Face_Pull', 'Face pull na polia', '["Use a corda na polia alta e segure as pontas com as palmas voltadas uma para a outra.","Puxe a corda em direção ao rosto abrindo os cotovelos para os lados.","Volte de forma controlada até estender os braços."]'::jsonb, '["Use carga moderada; o foco é a parte posterior do ombro."]'::jsonb, 'intermediate', 'reps', false, 'shoulder_iso', array[]::text[], '2026-10-27T00:00:00Z'),
  ('95c0bee1-3a87-5f97-aea3-32ce4a14b5bc', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Upright_Barbell_Row', 'Remada alta com barra', '["Em pé, segure a barra à frente das coxas com pegada na largura dos ombros.","Puxe a barra para cima junto ao corpo até a altura do peito, cotovelos acima das mãos.","Desça de forma controlada."]'::jsonb, '["Não eleve os cotovelos acima dos ombros se houver desconforto."]'::jsonb, 'intermediate', 'reps', false, 'shoulder_iso', array['shoulder_end_range']::text[], '2026-10-27T00:00:00Z'),
  ('2c5d0d8d-51ca-52d2-a2f5-45ac01eb24f2', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Wide-Grip_Lat_Pulldown', 'Puxada frontal aberta', '["Sente no aparelho com as coxas presas sob o apoio e segure a barra com pegada aberta.","Puxe a barra até a parte alta do peito, levando os cotovelos para baixo e para trás.","Volte de forma controlada até estender os braços."]'::jsonb, '["Não puxe a barra para trás da nuca."]'::jsonb, 'beginner', 'reps', false, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('9c5dbed1-d337-586a-afe1-7fdfb938957c', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Close-Grip_Front_Lat_Pulldown', 'Puxada frontal com pegada fechada', '["Sente no aparelho e segure a barra com as mãos próximas.","Puxe a barra até a parte alta do peito, inclinando levemente o tronco para trás.","Volte de forma controlada."]'::jsonb, '["Evite balançar o tronco para ganhar impulso."]'::jsonb, 'beginner', 'reps', false, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('600f21a4-88a7-5d9c-a776-7ac83c7b2910', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Underhand_Cable_Pulldowns', 'Puxada com pegada supinada', '["Segure a barra com as palmas voltadas para você, na largura dos ombros.","Puxe a barra até o peito levando os cotovelos junto ao corpo.","Volte de forma controlada."]'::jsonb, '["Mantenha o peito aberto durante a puxada."]'::jsonb, 'beginner', 'reps', false, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('abe8f757-012b-58b3-b5cd-4f4d820309f8', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Pullups', 'Barra fixa (pegada pronada)', '["Segure a barra com as palmas para a frente, um pouco mais abertas que os ombros.","Puxe o corpo até o queixo passar a barra.","Desça de forma controlada até estender os braços."]'::jsonb, '["Se não conseguir completar repetições, use a versão assistida com elástico."]'::jsonb, 'intermediate', 'reps', true, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('5ac2f521-00ac-52bc-8559-1ccc2622d68b', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Chin-Up', 'Barra fixa (pegada supinada)', '["Segure a barra com as palmas voltadas para você, na largura dos ombros.","Puxe o corpo até o queixo passar a barra.","Desça de forma controlada."]'::jsonb, '["Evite chutar as pernas para subir."]'::jsonb, 'intermediate', 'reps', true, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('f7958170-b6ed-5d4d-9967-56a6f89bf8eb', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Band_Assisted_Pull-Up', 'Barra fixa assistida com elástico', '["Prenda o elástico na barra e apoie um pé ou joelho na alça do elástico.","Segure a barra e puxe o corpo até o queixo passar a barra.","Desça de forma controlada."]'::jsonb, '["Verifique se o elástico está bem preso antes de começar."]'::jsonb, 'beginner', 'reps', true, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('ee0344c4-d201-5aab-88b5-1fadbe7899c9', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Straight-Arm_Pulldown', 'Pulldown com braços estendidos', '["Em pé, de frente para a polia alta, segure a barra com os braços estendidos.","Leve a barra até as coxas mantendo os cotovelos quase retos.","Volte de forma controlada até a altura dos olhos."]'::jsonb, '["Mantenha o tronco firme, levemente inclinado à frente."]'::jsonb, 'beginner', 'reps', false, 'v_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('f88f1fc5-cc7a-5554-8589-cdd74b166a8c', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Seated_Cable_Rows', 'Remada baixa sentada na polia', '["Sente com os pés apoiados e segure o triângulo com os braços estendidos.","Puxe em direção ao abdômen, aproximando as escápulas.","Volte de forma controlada sem curvar as costas."]'::jsonb, '["Não use o balanço do tronco para puxar."]'::jsonb, 'beginner', 'reps', false, 'h_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('9212c352-c333-54b7-b219-c282d2d50511', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Bent_Over_Barbell_Row', 'Remada curvada com barra', '["Segure a barra, flexione levemente os joelhos e incline o tronco à frente com as costas retas.","Puxe a barra em direção ao umbigo, aproximando as escápulas.","Desça de forma controlada."]'::jsonb, '["Mantenha a coluna neutra; se a lombar incomodar, prefira a remada apoiada."]'::jsonb, 'intermediate', 'reps', false, 'h_pull', array['axial_spine_load']::text[], '2026-10-27T00:00:00Z'),
  ('9461174d-c2fe-52db-a398-042679ecd69b', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'One-Arm_Dumbbell_Row', 'Remada unilateral com halter (serrote)', '["Apoie a mão e o joelho do mesmo lado no banco, com as costas retas.","Puxe o halter em direção ao quadril, levando o cotovelo para trás.","Desça de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Não gire o tronco para subir a carga."]'::jsonb, 'beginner', 'reps', false, 'h_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('dfa731d5-ad18-5761-ba05-5d53a2805b5a', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Incline_Row', 'Remada com halteres apoiada no banco inclinado', '["Deite de bruços num banco inclinado com um halter em cada mão.","Puxe os halteres para cima aproximando as escápulas.","Desça de forma controlada."]'::jsonb, '["Boa opção para poupar a lombar, já que o peito fica apoiado."]'::jsonb, 'beginner', 'reps', false, 'h_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('c2fecadc-08b9-5ebb-b49b-7ec2021e65d3', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Leverage_Iso_Row', 'Remada na máquina', '["Ajuste o assento e apoie o peito no encosto.","Puxe as manoplas para trás aproximando as escápulas.","Volte de forma controlada."]'::jsonb, '["Mantenha o peito em contato com o apoio."]'::jsonb, 'beginner', 'reps', false, 'h_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('3d288ce4-2c22-59a1-91b8-5f7c92bf679e', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'T-Bar_Row_with_Handle', 'Remada cavalinho (barra T)', '["Fique sobre a barra com os pés afastados e incline o tronco com as costas retas.","Puxe a pegada em direção ao peito.","Desça de forma controlada."]'::jsonb, '["Mantenha os joelhos levemente flexionados e a coluna neutra."]'::jsonb, 'intermediate', 'reps', false, 'h_pull', array['axial_spine_load']::text[], '2026-10-27T00:00:00Z'),
  ('6649eb5e-504a-5b72-8441-f6984aadf596', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Inverted_Row', 'Remada invertida', '["Posicione uma barra presa no suporte na altura da cintura e deite sob ela.","Segure a barra e mantenha o corpo alinhado, apoiado nos calcanhares.","Puxe o peito até a barra e desça de forma controlada."]'::jsonb, '["Quanto mais vertical o corpo, mais fácil o exercício."]'::jsonb, 'beginner', 'reps', true, 'h_pull', array[]::text[], '2026-10-27T00:00:00Z'),
  ('0ac327c4-5bfd-586e-900b-30accc5c012e', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Shrug', 'Encolhimento com halteres', '["Em pé, segure os halteres ao lado do corpo.","Eleve os ombros em direção às orelhas.","Desça de forma controlada."]'::jsonb, '["Não gire os ombros; o movimento é só para cima e para baixo."]'::jsonb, 'beginner', 'reps', false, 'shoulder_iso', array['neck_load']::text[], '2026-10-27T00:00:00Z'),
  ('3b0d76dd-c104-545d-add8-f94a12ba71cb', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Hyperextensions_Back_Extensions', 'Extensão lombar no banco (hiperextensão)', '["Ajuste o apoio na altura do quadril e prenda os pés.","Com as mãos cruzadas no peito, desça o tronco flexionando o quadril.","Suba até alinhar o tronco às pernas, sem arquear além disso."]'::jsonb, '["Não estenda a coluna além da linha do corpo."]'::jsonb, 'beginner', 'reps', false, 'hinge', array['spine_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('c1e685a2-8395-5507-a794-4b1ac2d0288c', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Superman', 'Superman (extensão lombar no solo)', '["Deite de bruços com os braços estendidos à frente.","Eleve braços, peito e pernas do chão ao mesmo tempo.","Segure por um instante e desça de forma controlada."]'::jsonb, '["Movimento curto e controlado; não force a extensão."]'::jsonb, 'beginner', 'reps', true, 'core_stability', array[]::text[], '2026-10-27T00:00:00Z'),
  ('7d9026b3-c17e-5bab-86a7-0425f1175a7f', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Squat', 'Agachamento livre com barra', '["Posicione a barra sobre a parte alta das costas e retire-a do suporte.","Afaste os pés na largura dos ombros, pontas levemente para fora.","Desça flexionando quadril e joelhos, com o peito aberto e a coluna neutra.","Suba empurrando o chão até estender quadril e joelhos."]'::jsonb, '["Ajuste as travas de segurança do suporte; aprenda o movimento com pouca carga."]'::jsonb, 'intermediate', 'reps', false, 'squat', array['axial_spine_load', 'deep_knee_flexion_loaded', 'hip_deep_flexion_loaded', 'technical_high']::text[], '2026-10-27T00:00:00Z'),
  ('cc3641d2-5783-589e-9012-f2d66cdc2685', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Front_Barbell_Squat', 'Agachamento frontal com barra', '["Apoie a barra na frente dos ombros com os cotovelos elevados.","Desça mantendo o tronco o mais vertical possível.","Suba empurrando o chão até estender quadril e joelhos."]'::jsonb, '["Exige mobilidade de punhos e tornozelos; comece com pouca carga."]'::jsonb, 'advanced', 'reps', false, 'squat', array['axial_spine_load', 'deep_knee_flexion_loaded', 'wrist_loaded_extension', 'technical_high']::text[], '2026-10-27T00:00:00Z'),
  ('1cfa3e6b-3cb9-5bfc-aa1f-71c19fa2a8ee', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Goblet_Squat', 'Agachamento goblet', '["Segure um halter (ou kettlebell) junto ao peito com as duas mãos.","Desça flexionando quadril e joelhos, mantendo o tronco ereto.","Suba empurrando o chão."]'::jsonb, '["Os joelhos devem acompanhar a direção das pontas dos pés."]'::jsonb, 'beginner', 'reps', false, 'squat', array['deep_knee_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('2ea0bf62-42fe-541c-8af2-5f5b6787607a', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Bodyweight_Squat', 'Agachamento com peso corporal', '["Fique em pé com os pés na largura dos ombros e os braços à frente.","Desça flexionando quadril e joelhos até onde mantiver a coluna neutra.","Suba empurrando o chão."]'::jsonb, '["Mantenha os calcanhares no chão."]'::jsonb, 'beginner', 'reps', true, 'squat', array[]::text[], '2026-10-27T00:00:00Z'),
  ('a4fb42f5-032d-5146-9d60-723d15936fcf', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Leg_Press', 'Leg press 45°', '["Sente no aparelho e apoie os pés na plataforma na largura dos ombros.","Destrave e desça a plataforma flexionando os joelhos, sem tirar o quadril do banco.","Empurre até quase estender os joelhos, sem travá-los."]'::jsonb, '["Não desça a ponto de a lombar sair do encosto."]'::jsonb, 'beginner', 'reps', false, 'squat', array['deep_knee_flexion_loaded', 'hip_deep_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('3c0448f4-6774-5b56-b509-5d58541945db', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Hack_Squat', 'Agachamento hack na máquina', '["Apoie as costas e os ombros no aparelho e os pés na plataforma.","Destrave e desça flexionando os joelhos.","Suba empurrando a plataforma até quase estender os joelhos."]'::jsonb, '["Ajuste a profundidade ao seu conforto nos joelhos."]'::jsonb, 'intermediate', 'reps', false, 'squat', array['deep_knee_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('19e3396c-e15c-59f7-a255-3c2f8a988163', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Smith_Machine_Squat', 'Agachamento no Smith', '["Posicione a barra do Smith sobre a parte alta das costas, com os pés levemente à frente.","Destrave e desça flexionando quadril e joelhos.","Suba até estender as pernas e trave a barra ao terminar."]'::jsonb, '["Ajuste as travas de segurança na altura mínima que você vai descer."]'::jsonb, 'beginner', 'reps', false, 'squat', array['axial_spine_load', 'deep_knee_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('6ab951ec-abdb-5085-bf6d-914570126664', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Lunges', 'Afundo com halteres', '["Em pé, segure os halteres ao lado do corpo.","Dê um passo à frente e desça até os dois joelhos formarem cerca de 90°.","Empurre com a perna da frente para voltar e alterne as pernas."]'::jsonb, '["O joelho de trás deve chegar perto do chão sem bater."]'::jsonb, 'beginner', 'reps', false, 'lunge', array['deep_knee_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('d9176df4-239d-52fc-946c-6a5c855e8beb', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Walking_Lunge', 'Afundo caminhando com barra', '["Posicione a barra sobre a parte alta das costas.","Dê um passo à frente e desça o joelho de trás em direção ao chão.","Suba e avance com a outra perna, caminhando."]'::jsonb, '["Exige espaço livre e equilíbrio; comece com pouca carga."]'::jsonb, 'intermediate', 'reps', false, 'lunge', array['axial_spine_load', 'deep_knee_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('526ac580-d49b-5fe0-bc3a-33847ba1831a', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Bodyweight_Walking_Lunge', 'Afundo caminhando com peso corporal', '["Em pé, com as mãos na cintura, dê um passo à frente.","Desça o joelho de trás em direção ao chão.","Suba e avance com a outra perna."]'::jsonb, '["Mantenha o tronco ereto."]'::jsonb, 'beginner', 'reps', true, 'lunge', array[]::text[], '2026-10-27T00:00:00Z'),
  ('e6668fa6-b460-52f2-9006-c9cc2bbe8751', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Split_Squat_with_Dumbbells', 'Afundo estático com halteres', '["Fique com uma perna à frente e outra atrás, halteres ao lado do corpo.","Desça o joelho de trás em direção ao chão sem mudar os pés de lugar.","Suba e complete a série antes de trocar de perna."]'::jsonb, '["Mantenha o peso distribuído no pé da frente."]'::jsonb, 'beginner', 'reps', false, 'lunge', array['deep_knee_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('d4a0347f-644c-5bb7-92d8-2e00a8224e75', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Step_Ups', 'Subida no banco com halteres', '["Fique de frente para um banco firme, halteres ao lado do corpo.","Apoie um pé inteiro no banco e suba estendendo essa perna.","Desça de forma controlada e alterne as pernas."]'::jsonb, '["Use um banco estável e de altura que mantenha o joelho confortável."]'::jsonb, 'intermediate', 'reps', false, 'lunge', array[]::text[], '2026-10-27T00:00:00Z'),
  ('16a58a2c-5ff7-5a49-b31a-1552afcf5a7e', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Plie_Dumbbell_Squat', 'Agachamento sumô com halter', '["Afaste bem os pés, com as pontas voltadas para fora, e segure um halter entre as pernas.","Desça flexionando joelhos e quadril, mantendo o tronco ereto.","Suba contraindo as coxas e os glúteos."]'::jsonb, '["Os joelhos devem seguir a direção das pontas dos pés."]'::jsonb, 'beginner', 'reps', false, 'squat', array[]::text[], '2026-10-27T00:00:00Z'),
  ('62240686-2942-5c2a-8acb-2bf2f7b8e14d', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Leg_Extensions', 'Cadeira extensora', '["Ajuste o encosto para o joelho ficar alinhado ao eixo do aparelho e o rolo sobre o tornozelo.","Estenda os joelhos até as pernas ficarem retas.","Desça de forma controlada."]'::jsonb, '["Evite cargas que façam o quadril sair do assento."]'::jsonb, 'beginner', 'reps', false, 'knee_ext', array[]::text[], '2026-10-27T00:00:00Z'),
  ('e68b2f41-c43c-5f6a-a904-a39af837bb0c', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Lying_Leg_Curls', 'Mesa flexora', '["Deite de bruços com o rolo logo acima dos calcanhares.","Flexione os joelhos trazendo os calcanhares em direção aos glúteos.","Desça de forma controlada."]'::jsonb, '["Mantenha o quadril apoiado no banco."]'::jsonb, 'beginner', 'reps', false, 'knee_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('a4540be7-1e8d-5be7-b08d-7e5594bf9179', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Seated_Leg_Curl', 'Cadeira flexora', '["Sente com o rolo atrás dos tornozelos e prenda as coxas sob o apoio.","Flexione os joelhos levando os calcanhares para baixo e para trás.","Volte de forma controlada."]'::jsonb, '["Ajuste o encosto para o joelho alinhar com o eixo do aparelho."]'::jsonb, 'beginner', 'reps', false, 'knee_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('3001dffb-44f0-5f40-a609-a37a840e8b04', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Natural_Glute_Ham_Raise', 'Flexora nórdica', '["Ajoelhe-se sobre um colchonete com os tornozelos presos sob um apoio firme ou segurados por alguém.","Com o corpo alinhado dos joelhos à cabeça, incline-se à frente o mais devagar possível.","Apoie as mãos no chão ao final e use-as para ajudar a voltar à posição inicial."]'::jsonb, '["Exercício intenso para os posteriores; comece com poucas repetições e pouca amplitude."]'::jsonb, 'advanced', 'reps', true, 'knee_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('318ba02a-ace3-5e7d-a3cb-4d6071f98584', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Romanian_Deadlift', 'Levantamento terra romeno com barra', '["Em pé, segure a barra à frente das coxas com os joelhos levemente flexionados.","Leve o quadril para trás descendo a barra rente às pernas, com as costas retas.","Desça até sentir o alongamento atrás das coxas e volte estendendo o quadril."]'::jsonb, '["Mantenha a barra próxima ao corpo e a coluna neutra."]'::jsonb, 'intermediate', 'reps', false, 'hinge', array['axial_spine_load', 'hip_deep_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('31828695-7429-533d-b579-57fbd186c144', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Stiff-Legged_Dumbbell_Deadlift', 'Stiff com halteres', '["Em pé, segure os halteres à frente das coxas.","Com os joelhos quase estendidos, leve o quadril para trás e desça os halteres rente às pernas.","Volte estendendo o quadril."]'::jsonb, '["Desça só até onde mantiver as costas retas."]'::jsonb, 'beginner', 'reps', false, 'hinge', array['axial_spine_load', 'hip_deep_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('a39364cc-1afe-500c-8b88-b232a4502e45', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Deadlift', 'Levantamento terra com barra', '["Fique com a barra sobre o meio dos pés e segure-a logo fora das pernas.","Com as costas retas e o peito aberto, empurre o chão estendendo quadril e joelhos juntos.","Fique ereto no alto e desça a barra pelo mesmo caminho."]'::jsonb, '["Aprenda com pouca carga; a coluna deve permanecer neutra do início ao fim."]'::jsonb, 'intermediate', 'reps', false, 'hinge', array['axial_spine_load', 'hip_deep_flexion_loaded', 'technical_high']::text[], '2026-10-27T00:00:00Z'),
  ('c0e12aa4-85fc-527a-b71d-b4db85a383bb', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Hip_Thrust', 'Elevação pélvica com barra', '["Apoie a parte alta das costas no banco e a barra sobre o quadril, com proteção.","Com os pés firmes no chão, eleve o quadril até alinhar tronco e coxas.","Desça de forma controlada."]'::jsonb, '["Use uma almofada sob a barra para proteger o quadril."]'::jsonb, 'intermediate', 'reps', false, 'hinge', array[]::text[], '2026-10-27T00:00:00Z'),
  ('3becb61f-a100-51d0-8175-e51334937479', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Glute_Bridge', 'Ponte de glúteo com barra', '["Deite de costas no chão com a barra sobre o quadril e os joelhos flexionados.","Eleve o quadril contraindo os glúteos.","Desça de forma controlada."]'::jsonb, '["Use uma almofada sob a barra."]'::jsonb, 'intermediate', 'reps', false, 'hinge', array[]::text[], '2026-10-27T00:00:00Z'),
  ('ea6e8940-c829-512e-88df-0a0119b55801', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Single_Leg_Glute_Bridge', 'Ponte de glúteo unilateral', '["Deite de costas com um pé apoiado no chão e a outra perna estendida.","Eleve o quadril empurrando o pé de apoio.","Desça de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Mantenha o quadril nivelado durante a subida."]'::jsonb, 'beginner', 'reps', true, 'hinge', array[]::text[], '2026-10-27T00:00:00Z'),
  ('7032d635-010f-5b94-b6b2-8af24de2aaf6', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Glute_Kickback', 'Coice de glúteo no solo', '["Fique em quatro apoios com as mãos sob os ombros.","Estenda uma perna para trás e para cima contraindo o glúteo.","Volte de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Não arqueie a lombar ao subir a perna."]'::jsonb, 'beginner', 'reps', true, 'hinge', array['wrist_loaded_extension']::text[], '2026-10-27T00:00:00Z'),
  ('4dadb079-e427-519c-8030-1afcb9b1d305', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'One-Legged_Cable_Kickback', 'Coice de glúteo na polia', '["Prenda a tornozeleira na polia baixa e fique de frente para o aparelho, segurando-o.","Leve a perna estendida para trás contraindo o glúteo.","Volte de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Mantenha o tronco firme, sem balançar."]'::jsonb, 'beginner', 'reps', false, 'hinge', array[]::text[], '2026-10-27T00:00:00Z'),
  ('8203f60f-f293-550a-b4ae-cff5f753c2c1', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Thigh_Abductor', 'Cadeira abdutora', '["Sente com as pernas encostadas nos apoios internos.","Afaste as pernas empurrando os apoios para fora.","Volte de forma controlada."]'::jsonb, '["Use amplitude confortável para o quadril."]'::jsonb, 'beginner', 'reps', false, 'hip_abd_add', array[]::text[], '2026-10-27T00:00:00Z'),
  ('cc410b31-1393-5720-bc2e-9de55ce2d2f9', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Thigh_Adductor', 'Cadeira adutora', '["Sente com as pernas abertas e os apoios na parte interna dos joelhos.","Junte as pernas contraindo a parte interna das coxas.","Volte de forma controlada."]'::jsonb, '["Ajuste a abertura inicial a uma amplitude confortável."]'::jsonb, 'beginner', 'reps', false, 'hip_abd_add', array[]::text[], '2026-10-27T00:00:00Z'),
  ('38ddca4d-c63c-5ed4-8359-6bcbbf45b722', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Monster_Walk', 'Caminhada lateral com elástico', '["Coloque o elástico acima dos joelhos ou nos tornozelos e semiflexione as pernas.","Dê passos laterais curtos mantendo a tensão no elástico.","Volte para o outro lado com o mesmo número de passos."]'::jsonb, '["Mantenha os joelhos apontados para a frente."]'::jsonb, 'beginner', 'reps', false, 'hip_abd_add', array[]::text[], '2026-10-27T00:00:00Z'),
  ('a746e3c0-6020-5f37-9318-c5d1fb39a8c8', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Band_Hip_Adductions', 'Adução de quadril com elástico', '["Prenda o elástico num ponto fixo baixo e no tornozelo mais próximo.","Leve a perna em direção à outra, cruzando à frente do corpo.","Volte de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Apoie-se em algo firme para manter o equilíbrio."]'::jsonb, 'beginner', 'reps', false, 'hip_abd_add', array[]::text[], '2026-10-27T00:00:00Z'),
  ('ba1b3f33-8ef6-5311-92cd-8eaddf5bdf70', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Standing_Calf_Raises', 'Panturrilha em pé na máquina', '["Posicione os ombros sob os apoios e a ponta dos pés na borda da plataforma.","Eleve os calcanhares o máximo possível.","Desça até sentir o alongamento da panturrilha."]'::jsonb, '["Faça o movimento completo, sem quicar."]'::jsonb, 'beginner', 'reps', false, 'calf', array[]::text[], '2026-10-27T00:00:00Z'),
  ('2f2f4492-10c9-573f-b208-dd076a6a8eba', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Seated_Calf_Raise', 'Panturrilha sentado', '["Sente com o apoio sobre as coxas e a ponta dos pés na plataforma.","Eleve os calcanhares o máximo possível.","Desça até sentir o alongamento."]'::jsonb, '["Controle a descida."]'::jsonb, 'beginner', 'reps', false, 'calf', array[]::text[], '2026-10-27T00:00:00Z'),
  ('804f40c1-9206-5962-8c08-7d32fdd5c327', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Calf_Press_On_The_Leg_Press_Machine', 'Panturrilha no leg press', '["Sente no leg press com a ponta dos pés na borda inferior da plataforma e as pernas estendidas.","Empurre a plataforma com a ponta dos pés.","Volte de forma controlada."]'::jsonb, '["Mantenha a trava de segurança ao alcance e os joelhos sem travar."]'::jsonb, 'beginner', 'reps', false, 'calf', array[]::text[], '2026-10-27T00:00:00Z'),
  ('060c3f48-3394-5abd-beeb-5a4c89c6f37c', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Standing_Dumbbell_Calf_Raise', 'Panturrilha em pé com halteres', '["Em pé, com halteres ao lado do corpo e a ponta dos pés sobre um degrau.","Eleve os calcanhares o máximo possível.","Desça até sentir o alongamento."]'::jsonb, '["Apoie uma das mãos para ter equilíbrio, se necessário."]'::jsonb, 'beginner', 'reps', false, 'calf', array[]::text[], '2026-10-27T00:00:00Z'),
  ('821a6fb8-6602-5adf-8537-015bb556f214', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Barbell_Curl', 'Rosca direta com barra', '["Em pé, segure a barra com as palmas para a frente, na largura dos ombros.","Flexione os cotovelos trazendo a barra até a altura do peito.","Desça de forma controlada."]'::jsonb, '["Mantenha os cotovelos junto ao corpo, sem balançar o tronco."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('80d167aa-ab10-58e7-aec3-269c9eeff3e4', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'EZ-Bar_Curl', 'Rosca direta com barra W', '["Segure a barra W nas partes inclinadas com as palmas para cima.","Flexione os cotovelos trazendo a barra até o peito.","Desça de forma controlada."]'::jsonb, '["A barra W costuma ser mais confortável para os punhos."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('ffafc5c0-14e3-5810-af0f-f5d6f3cb7246', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dumbbell_Alternate_Bicep_Curl', 'Rosca alternada com halteres', '["Em pé, segure os halteres ao lado do corpo.","Flexione um cotovelo girando a palma para cima ao subir.","Desça de forma controlada e alterne os braços."]'::jsonb, '["Evite usar impulso do tronco."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('28cacfdf-f7ac-53fe-8ad7-324c62bf4620', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Hammer_Curls', 'Rosca martelo', '["Segure os halteres com as palmas voltadas para o corpo.","Flexione os cotovelos mantendo essa pegada.","Desça de forma controlada."]'::jsonb, '["Mantenha os cotovelos fixos ao lado do corpo."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('0a038e72-0ef1-56f2-aa24-cc2eedcbf557', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Incline_Dumbbell_Curl', 'Rosca inclinada com halteres', '["Sente num banco inclinado com os braços estendidos para baixo.","Flexione os cotovelos sem tirar os braços da posição.","Desça de forma controlada até estender."]'::jsonb, '["Use cargas menores que na rosca em pé."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('76dd6178-f8d4-5a6d-84fe-b2b5db327fd2', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Concentration_Curls', 'Rosca concentrada', '["Sente no banco e apoie o cotovelo na parte interna da coxa.","Flexione o cotovelo trazendo o halter em direção ao ombro.","Desça de forma controlada e troque de braço ao fim da série."]'::jsonb, '["Mantenha o braço parado; só o antebraço se move."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('2769a12d-d06d-5afa-9a8d-4cb9c6e62412', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Preacher_Curl', 'Rosca Scott com barra', '["Sente no banco Scott com a parte de trás dos braços sobre o apoio.","Flexione os cotovelos trazendo a barra até perto dos ombros.","Desça de forma controlada sem estender bruscamente."]'::jsonb, '["Não solte o peso no final da descida."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('128492d0-5918-52b7-a269-b65e561de2c5', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Standing_Biceps_Cable_Curl', 'Rosca na polia', '["De frente para a polia baixa, segure a barra com as palmas para cima.","Flexione os cotovelos até a barra chegar perto do peito.","Volte de forma controlada."]'::jsonb, '["Mantenha os cotovelos junto ao corpo."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('b1694c78-0a32-5643-bd5f-3beecfa67e63', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Machine_Bicep_Curl', 'Rosca na máquina', '["Ajuste o assento para o cotovelo ficar alinhado ao eixo do aparelho.","Flexione os cotovelos até o fim do movimento.","Volte de forma controlada."]'::jsonb, '["Não tire os braços do apoio."]'::jsonb, 'beginner', 'reps', false, 'elbow_flex', array[]::text[], '2026-10-27T00:00:00Z'),
  ('9bd8a00f-7498-56d2-a6e9-d4decc7e8a84', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Palms-Up_Dumbbell_Wrist_Curl_Over_A_Bench', 'Rosca de punho com halteres', '["Ajoelhe-se com os antebraços apoiados no banco e as palmas para cima, punhos para fora da borda.","Flexione os punhos elevando os halteres.","Desça de forma controlada."]'::jsonb, '["Use cargas leves; o movimento é curto."]'::jsonb, 'beginner', 'reps', false, 'carry_grip', array[]::text[], '2026-10-27T00:00:00Z'),
  ('f82a6e59-ccff-5001-bef5-c1792c2cd3e9', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Palms-Down_Dumbbell_Wrist_Curl_Over_A_Bench', 'Rosca de punho inversa com halteres', '["Apoie os antebraços no banco com as palmas para baixo, punhos para fora da borda.","Estenda os punhos elevando os halteres.","Desça de forma controlada."]'::jsonb, '["Use cargas leves."]'::jsonb, 'beginner', 'reps', false, 'carry_grip', array[]::text[], '2026-10-27T00:00:00Z'),
  ('f4e786d4-6186-52f2-a888-9d216b19b535', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Farmers_Walk', 'Caminhada do fazendeiro', '["Segure um halter pesado em cada mão ao lado do corpo.","Caminhe com passos curtos, tronco ereto e ombros firmes.","Percorra a distância ou o tempo combinado e apoie os halteres no chão com cuidado."]'::jsonb, '["Escolha um percurso livre de obstáculos."]'::jsonb, 'intermediate', 'duration', false, 'carry_grip', array[]::text[], '2026-10-27T00:00:00Z'),
  ('83f5b572-8855-5c99-aa52-14c80a0a15c6', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Triceps_Pushdown', 'Tríceps na polia com barra', '["De frente para a polia alta, segure a barra com os cotovelos junto ao corpo.","Estenda os cotovelos levando a barra até as coxas.","Volte de forma controlada até a altura do peito."]'::jsonb, '["Os cotovelos devem ficar parados ao lado do corpo."]'::jsonb, 'beginner', 'reps', false, 'elbow_ext', array[]::text[], '2026-10-27T00:00:00Z'),
  ('4be9770f-3dc8-5031-92ad-955dcd2204cc', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Triceps_Pushdown_-_Rope_Attachment', 'Tríceps na polia com corda', '["Segure a corda na polia alta com os cotovelos junto ao corpo.","Estenda os cotovelos afastando as pontas da corda no final.","Volte de forma controlada."]'::jsonb, '["Não incline o tronco para ajudar."]'::jsonb, 'beginner', 'reps', false, 'elbow_ext', array[]::text[], '2026-10-27T00:00:00Z'),
  ('a61cfdc4-6c9f-53b9-804c-4976df336280', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Triceps_Overhead_Extension_with_Rope', 'Tríceps francês na polia com corda', '["De costas para a polia, segure a corda atrás da cabeça com os cotovelos apontados para a frente.","Estenda os cotovelos levando a corda à frente e acima da cabeça.","Volte de forma controlada."]'::jsonb, '["Mantenha o abdômen firme para não arquear a lombar."]'::jsonb, 'beginner', 'reps', false, 'elbow_ext', array['overhead']::text[], '2026-10-27T00:00:00Z'),
  ('5f9ffac6-66b2-5731-ae45-45dc962222a1', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'EZ-Bar_Skullcrusher', 'Tríceps testa com barra W', '["Deite no banco segurando a barra W acima do peito com os braços estendidos.","Flexione os cotovelos descendo a barra em direção à testa.","Estenda os cotovelos de volta, sem mover os braços."]'::jsonb, '["Use carga moderada e desça devagar."]'::jsonb, 'intermediate', 'reps', false, 'elbow_ext', array['elbow_loaded_extension']::text[], '2026-10-27T00:00:00Z'),
  ('a058997e-6eb3-50ce-b217-7e21c07f3663', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Standing_Dumbbell_Triceps_Extension', 'Tríceps francês com halter', '["Segure um halter com as duas mãos acima da cabeça.","Flexione os cotovelos descendo o halter atrás da cabeça.","Estenda os cotovelos de volta."]'::jsonb, '["Pode ser feito sentado para mais estabilidade."]'::jsonb, 'beginner', 'reps', false, 'elbow_ext', array['overhead']::text[], '2026-10-27T00:00:00Z'),
  ('d8c45998-59df-5bbd-b60d-9042a342a955', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Tricep_Dumbbell_Kickback', 'Tríceps coice com halter', '["Apoie mão e joelho no banco e mantenha o braço de trabalho junto ao corpo, cotovelo a 90°.","Estenda o cotovelo levando o halter para trás.","Volte de forma controlada e troque de lado ao fim da série."]'::jsonb, '["Só o antebraço se move."]'::jsonb, 'beginner', 'reps', false, 'elbow_ext', array[]::text[], '2026-10-27T00:00:00Z'),
  ('002883e5-c011-510c-9de5-8a65195fd31f', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Bench_Dips', 'Mergulho no banco', '["Apoie as mãos na borda de um banco atrás de você, com as pernas à frente.","Desça o corpo flexionando os cotovelos.","Empurre até estender os braços."]'::jsonb, '["Desça só até onde o ombro fica confortável."]'::jsonb, 'beginner', 'reps', true, 'elbow_ext', array['shoulder_end_range', 'wrist_loaded_extension']::text[], '2026-10-27T00:00:00Z'),
  ('0493a64a-2a1f-535f-9ca0-ca372cc813d9', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dips_-_Triceps_Version', 'Paralelas com ênfase no tríceps', '["Apoie-se nas barras paralelas com o tronco ereto e os braços estendidos.","Desça flexionando os cotovelos, mantendo-os junto ao corpo.","Empurre até estender os braços."]'::jsonb, '["Desça só até onde o ombro fica confortável."]'::jsonb, 'intermediate', 'reps', true, 'elbow_ext', array['shoulder_end_range']::text[], '2026-10-27T00:00:00Z'),
  ('9f0b1b8f-00f2-54e3-bf93-3e0f388c7bda', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Machine_Triceps_Extension', 'Tríceps na máquina', '["Ajuste o assento para o cotovelo alinhar com o eixo do aparelho.","Estenda os cotovelos até o fim do movimento.","Volte de forma controlada."]'::jsonb, '["Não tire os braços do apoio."]'::jsonb, 'beginner', 'reps', false, 'elbow_ext', array[]::text[], '2026-10-27T00:00:00Z'),
  ('bc0af24a-2b6b-5e93-8d07-83a14aa9ef90', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Plank', 'Prancha', '["Apoie os antebraços no chão com os cotovelos sob os ombros.","Estenda as pernas e alinhe o corpo da cabeça aos calcanhares.","Mantenha a posição contraindo abdômen e glúteos pelo tempo prescrito."]'::jsonb, '["Não deixe o quadril cair nem subir demais."]'::jsonb, 'beginner', 'duration', true, 'core_stability', array[]::text[], '2026-10-27T00:00:00Z'),
  ('b733acd4-6e40-5c02-b452-290f34fd1e59', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Side_Bridge', 'Prancha lateral', '["Deite de lado e apoie o antebraço no chão, cotovelo sob o ombro.","Eleve o quadril alinhando o corpo.","Mantenha a posição pelo tempo prescrito e troque de lado."]'::jsonb, '["Se ficar difícil, apoie o joelho de baixo."]'::jsonb, 'beginner', 'duration', true, 'core_stability', array[]::text[], '2026-10-27T00:00:00Z'),
  ('215c0e23-f2ef-586f-a804-698a6e5fe240', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Dead_Bug', 'Dead bug', '["Deite de costas com os braços para cima e os joelhos e quadris a 90°.","Estenda um braço para trás e a perna oposta à frente, sem tirar a lombar do chão.","Volte e alterne os lados."]'::jsonb, '["Movimento lento; a lombar deve permanecer apoiada."]'::jsonb, 'beginner', 'reps', true, 'core_stability', array[]::text[], '2026-10-27T00:00:00Z'),
  ('f53ff083-da31-5d75-9c81-d5774ec8672f', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Crunches', 'Abdominal supra', '["Deite de costas com os joelhos flexionados e os pés no chão.","Eleve os ombros do chão contraindo o abdômen.","Desça de forma controlada."]'::jsonb, '["Não puxe a cabeça com as mãos."]'::jsonb, 'beginner', 'reps', true, 'core_flexion', array[]::text[], '2026-10-27T00:00:00Z'),
  ('2060be6a-fbad-516b-8c9b-08a4a61ea770', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Cable_Crunch', 'Abdominal na polia ajoelhado', '["Ajoelhe-se de frente para a polia alta segurando a corda junto à cabeça.","Flexione o tronco levando os cotovelos em direção aos joelhos.","Volte de forma controlada."]'::jsonb, '["O movimento vem do abdômen, não do quadril."]'::jsonb, 'intermediate', 'reps', false, 'core_flexion', array['spine_flexion_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('b8ce15a6-538f-5ee7-b6e1-273ecb950270', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Reverse_Crunch', 'Abdominal infra (reverso)', '["Deite de costas com os joelhos flexionados e os pés fora do chão.","Eleve o quadril trazendo os joelhos em direção ao peito.","Desça de forma controlada."]'::jsonb, '["Evite usar impulso das pernas."]'::jsonb, 'beginner', 'reps', true, 'core_flexion', array[]::text[], '2026-10-27T00:00:00Z'),
  ('fa63444f-fcff-5057-88a3-caedc980c75d', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Hanging_Leg_Raise', 'Elevação de pernas na barra fixa', '["Pendure-se na barra fixa com os braços estendidos.","Eleve as pernas até a altura do quadril ou acima, sem balançar.","Desça de forma controlada."]'::jsonb, '["Comece com os joelhos flexionados se a versão estendida for difícil."]'::jsonb, 'advanced', 'reps', true, 'core_flexion', array[]::text[], '2026-10-27T00:00:00Z'),
  ('d1648501-0790-5530-8b77-d246e3899c31', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Flat_Bench_Lying_Leg_Raise', 'Elevação de pernas deitado no banco', '["Deite no banco segurando a borda atrás da cabeça.","Eleve as pernas estendidas até a vertical.","Desça devagar sem encostar os pés no chão."]'::jsonb, '["Mantenha a lombar apoiada no banco."]'::jsonb, 'beginner', 'reps', true, 'core_flexion', array[]::text[], '2026-10-27T00:00:00Z'),
  ('96e11940-48f5-5f74-9ee3-229dc125106d', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Oblique_Crunches_-_On_The_Floor', 'Abdominal oblíquo', '["Deite de costas com os joelhos flexionados e caídos para um lado.","Eleve os ombros do chão contraindo a lateral do abdômen.","Desça e troque de lado ao fim da série."]'::jsonb, '["Não puxe o pescoço."]'::jsonb, 'beginner', 'reps', true, 'core_flexion', array[]::text[], '2026-10-27T00:00:00Z'),
  ('2fbcbcb0-8166-5c7b-b80b-90783edeefaa', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Russian_Twist', 'Rotação russa', '["Sente com os joelhos flexionados e o tronco inclinado para trás, pés no chão ou elevados.","Gire o tronco de um lado para o outro, levando as mãos ao lado do quadril.","Mantenha o abdômen firme durante todo o movimento."]'::jsonb, '["Evite se houver desconforto na coluna; prefira o Pallof press."]'::jsonb, 'intermediate', 'reps', true, 'core_flexion', array['spine_rotation_loaded']::text[], '2026-10-27T00:00:00Z'),
  ('1a66c18a-7365-5e81-aa96-d77c34439dac', 'imported', '33deab4c-1189-55d5-a91d-8726ee32c15c', 'Pallof_Press', 'Pallof press (antirrotação na polia)', '["Fique de lado para a polia na altura do peito, segurando a alça junto ao esterno.","Estenda os braços à frente sem deixar o tronco girar.","Volte as mãos ao peito e troque de lado ao fim da série."]'::jsonb, '["A resistência deve tentar girar o tronco; você não deixa."]'::jsonb, 'beginner', 'reps', false, 'core_stability', array[]::text[], '2026-10-27T00:00:00Z');


